def stepinfo_3d(pos_actual_3xn, pos_target_3, t, settling_threshold=0.02):
    pos_actual_3xn = np.asarray(pos_actual_3xn, dtype=float)
    pos_target_3 = np.asarray(pos_target_3, dtype=float).reshape(3)
    t = np.asarray(t, dtype=float).reshape(-1)

    dist = np.linalg.norm(pos_actual_3xn.T - pos_target_3[None, :], axis=1)

    if dist.size == 0 or dist[0] < 1e-6:
        return {
            'RiseTime': 0.0,
            'SettlingTime': 0.0,
            'Overshoot_pct': 0.0,
            'SteadyStateError': float(dist[-1]) if dist.size else 0.0,
        }

    d0 = float(dist[0])

    rise_time = 0.0
    for k in range(dist.size):
        if dist[k] <= 0.1 * d0:
            rise_time = float(t[k])
            break

    band = settling_threshold * d0
    settling_time = float(t[-1])
    for k in range(dist.size - 1, -1, -1):
        if dist[k] > band:
            settling_time = float(t[k])
            break

    first_entry = None
    for k in range(dist.size):
        if dist[k] <= band:
            first_entry = k
            break

    if first_entry is None:
        overshoot_pct = 0.0
    else:
        max_post = float(np.max(dist[first_entry:]))
        overshoot_pct = 100.0 * max_post / d0

    return {
        'RiseTime': float(rise_time),
        'SettlingTime': float(settling_time),
        'Overshoot_pct': float(overshoot_pct),
        'SteadyStateError': float(dist[-1]),
    }
"}

